-----------------------------------------------------------------
-- 单独管理 春节迷宫内的 role ui元件
-- 将本脚本 挂载到 SpringFestivalMazeRoleCanvas 节点上
-----------------------------------------------------------------


---@class MazeUI_Role
---@field uiSwitchImage     Game.Native.Common.UISwitchImage
---@field roleTF            UnityEngine.RectTransform     
---@field animationComp     UnityEngine.Animation
---@field edgeRoleUIBH        Engine.Modules.LuaBehaviour -- MazeUI_EdgeRole
local MazeUI_Role = Class('MazeUI_Role')

-- ========================================================

--- lua:


local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

--local MazeMain = import('Game.Behaviours.Maze.MazeMain')
local MazeMain              = import('Game.Behaviours.Maze.MazeMain')

---@type Maze2DStates
local Maze2DStates = import('Game.Behaviours.Maze.Maze2DStates')

---@type Engine.UI.UIRaycastBlocker
local UIRaycastBlocker = CS.Engine.UI.UIRaycastBlocker.Instance

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Transform = CS.UnityEngine.Transform
local RectTransform = CS.UnityEngine.RectTransform
local Canvas = CS.UnityEngine.Canvas
local Animation = CS.UnityEngine.Animation
local Screen = CS.UnityEngine.Screen
local Mathf = CS.UnityEngine.Mathf
local Time = CS.UnityEngine.Time
local Quaternion = CS.UnityEngine.Quaternion

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local Vector3 = CS.UnityEngine.Vector3
local UISwitchImage = CS.Game.Native.Common.UISwitchImage
local URPCameraController = CS.Game.Native.URP.URPCameraController


-- ========================================================


local screenBoundaryTrackRadius_ = 0.7 -- edgeRole 与屏幕边框的距离



-- ========================================================



function MazeUI_Role:__init()
    self._isInit = false
    self.vcamHalfSize = {}
    self.isShow = true -- 总显示开关
    self.isInScreen = true
end


function MazeUI_Role:__delete()
    self.roleCanvas = nil 
    self.roleTF = nil 
    self.movePivotTF = nil
end



function MazeUI_Role:Start()
    KTool.SetActive(self.controller.gameObject, true)
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:


    self.transform = self.controller.gameObject.transform

    assert( self.uiSwitchImage )
    assert( self.roleTF )      -- 主 role ui, 平滑地靠近 movePivotTF
    --assert( self.movePivotTF ) -- 真正沿着 曲线轨道运动的 tf
    assert( self.edgeRoleUIBH )
    assert( self.animationComp )


    -- 新建一个 movePivot: 
    self.movePivotGO = GameObject("MovePivot_2_")
    self.movePivotTF = self.movePivotGO.transform 
    self.movePivotTF:SetParent( self.controller.gameObject.transform ) 


    self.edgeRoleUI = self.edgeRoleUIBH.Env 
    assert( self.edgeRoleUI )

    self.roleCanvas =  KTool.GetComponent(self.roleTF.gameObject, typeof(Canvas))
    assert( self.roleCanvas )


    local parentCanvas =  KTool.GetComponent(self.controller.gameObject, typeof(Canvas))
    assert( parentCanvas )
    parentCanvas.worldCamera = URPCameraController.Instance.mainCamera -- !!!!!!! MUST 否则这个 canvas 的射线检测坐标系会错位


    -- 设置 男/女 头像:
    local isMale = not CfUtils.IsWoman()
    self.uiSwitchImage.Status = (isMale==true) and 2 or 1


    self.idleAnimName  = "SpringFestivalMazeRoleMoveNode_Role_idle"
    self.eventAnimName = "SpringFestivalMazeRoleMoveNode_Role_event"
    self.hideAnimName = "SpringFestivalMazeRoleMoveNode_Alpha1"
    self.showAnimName = "SpringFestivalMazeRoleMoveNode_Alpha2"


    -- 立马播放 idle 动画:
    self.animationComp:Play(self.idleAnimName)


    self.co_0 = cs_coroutine.start(self.DelayInit, self)
end 


function MazeUI_Role:Prepare( vcam_, cameraPivot_, mazeInput_ )
    self.vcam = vcam_
    self.cameraPivot = cameraPivot_
    self.mazeInput = mazeInput_
end




function MazeUI_Role:DelayInit() 

    -- 等待 Prepare()
    while self.vcam == nil do 
        coroutine.yield(Yielders.EndOfFrame)
    end     

    self.edgeRoleUI.button.onClick:AddListener( function()

        --print( "-- 按下 edge role UI --" )

        if Maze2DStates.IsInAutoControlLegal() == true  then


            -- --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl + 1 -- !!! Must
            -- Maze2DStates.AddIsInAutoControl() -- !!! Must 
            -- self.co_1 = cs_coroutine.start(function()
            --     cs_coroutine.yield_return(MazeMain.MoveTo2( self.cameraPivot, self.mazeInput:CalcSafetyPos(self.roleTF.position), {smoothTime = 0.3, maxSpeed = 30.0} ))
            --     --Maze2DStates.isInAutoControl = Maze2DStates.isInAutoControl - 1 -- !!! Must
            --     Maze2DStates.MinusIsInAutoControl() -- !!! Must 
            -- end)

            ---
            UIRaycastBlocker:AddCondition("MazeUI_Role.DelayInit")    
            cs_coroutine.start(function()
                UIRaycastBlocker:RemoveCondition("MazeUI_Role.DelayInit")
                cs_coroutine.yield_return(MazeMain.MoveTo2( self.cameraPivot, self.mazeInput:CalcSafetyPos(self.roleTF.position), {smoothTime = 0.3, maxSpeed = 30.0} ))
            end)

        end 

    end)

    self._isInit = true
end 




function MazeUI_Role:OnDestroy()

    if not isNull(self.movePivotGO) then 
        Object.Destroy( self.movePivotGO )
    end

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



-- 专门为了平滑 roleTF 的运动 而存在;
function MazeUI_Role:Update()

    -- 确保这个值一定在衰减:
    if Maze2DStates.quitWaitFrames > -100 then 
        Maze2DStates.quitWaitFrames = Maze2DStates.quitWaitFrames - 1
    end

    --print( "isInAutoControl = " .. Maze2DStates.isInAutoControl )

    if self._isInit ~= true then 
        return
    end
    --- roleTF 平滑地靠近 movePivotTF: 
    self.roleTF.position = Vector3.Lerp( self.roleTF.position, self.movePivotTF.position, 0.15 )
end


-- =============================================================== Self -> ================================================================== -- 


-- 需被 MazeMain 调用
function MazeUI_Role:SelfUpdate()
    if self._isInit ~= true then 
        return
    end
    -----  

    self:FreshVCamDatas() 

    self.isInScreen = self:IsRoleInScreen() 
    self:FreshShow()

    -- self.edgeRoleUI.transform.position = self.vcam.transform.position
    -- local p = self.edgeRoleUI.transform.position
    -- p.y = 0 
    -- self.edgeRoleUI.transform.position = p

    if self.isInScreen ~= true then 
        self:CalcEdgeRolePos()
    end 

end


-- 严格沿着曲线运动的点
function MazeUI_Role:RolePivotTF()
    --return self.roleTF
    return self.movePivotTF
end

-- 平滑的点
function MazeUI_Role:RoleTFPos()
    return self.roleTF.position
end

-- 硬跳到目标点
function MazeUI_Role:SetRolePosImmediately( pos_ )
    self.roleTF.position = pos_
    self.movePivotTF.position = pos_
end




-- 外部设置 显示总开关
function MazeUI_Role:SetIsShow( isShow )
    self.isShow = isShow
    self:FreshShow()
end 



-- 管理 role, edgeRole 是否显示:
function MazeUI_Role:FreshShow()
    if self.isShow == false then 
        -- 全隐藏
        self:ShowRole( false )
        self.edgeRoleUI:ShowRole( false )
    else 
        self:ShowRole( self.isInScreen )
        self.edgeRoleUI:ShowRole( not self.isInScreen )
    end 
end



function MazeUI_Role:ShowRole( isShow )
    if self.roleCanvas.enabled ~= isShow then 
        self.roleCanvas.enabled = isShow
    end 
end





---@return void
function MazeUI_Role:PlayAnimationEvent()
    self.animationComp:Play(self.eventAnimName)
end




-- 执行 role 瞬移的 开始/结束 阶段
---@param trackPesist SimpleTrack.TrackPesist
---@param isShow boolean
---@return System.Collections.IEnumerator
function MazeUI_Role:RoleTeleporting(trackPesist, isShow )

    if( trackPesist.isTeleporting == false ) then
        return -- yield break;
    end

    if isShow then 
        self.animationComp:Play(self.showAnimName)
    else 
        self.animationComp:Play(self.hideAnimName)
    end

    --cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
end




function MazeUI_Role:FreshVCamDatas()

    local lens = self.vcam.m_Lens
    self.vcamHalfSize.y = lens.OrthographicSize
    self.vcamHalfSize.x = (Screen.width / Screen.height) * self.vcamHalfSize.y

end 



function MazeUI_Role:IsRoleInScreen()
    local offset = self.roleTF.position - self.vcam.transform.position -- Vector3 (x,z)有用
    --print( "offset = " .. offset:ToString() .. "\n vcamHalfSize = " .. self.vcamHalfSize.x .. ", " .. self.vcamHalfSize.y ) 
    return      (Mathf.Abs(offset.x) < self.vcamHalfSize.x) 
            and (Mathf.Abs(offset.z) < self.vcamHalfSize.y) 
end 




function MazeUI_Role:CalcEdgeRolePos()

    -- 计算 edgeRole 的 pos:
    local w = self.vcamHalfSize.x
    local h = self.vcamHalfSize.y 

    local innW = w - screenBoundaryTrackRadius_ -- inn halfW
    local innH = h - screenBoundaryTrackRadius_ -- inn halfH

    local p = self.roleTF.position - self.vcam.transform.position -- Vector3 (x,z)有用

    -- local dir = p.normalized
    -- dir.y = 0 
    -- dir = dir.normalized

    p.x = (p.x > innW) and innW or ((p.x < -innW) and -innW or p.x)
    p.z = (p.z > innH) and innH or ((p.z < -innH) and -innH or p.z)
    self.edgeRoleUI.transform.position = self.vcam.transform.position + p

    -- 计算 edgeRole arrow 的朝向: 

    local dir = self.roleTF.position - self.edgeRoleUI.transform.position
    dir.y = 0 
    dir = dir.normalized

    local angle = Vector3.SignedAngle( Vector3( -1,0,0 ), dir, Vector3.up )
    -- print( "angle = " .. angle )

    self.edgeRoleUI.arrowRTF.rotation = Quaternion.Euler( 90, 0, - angle )


end







return MazeUI_Role
